#!/bin/sh
# Tests the classi-staging files of D-08 (supabase/staging/*d08*.sql, generated by scripts/staging/gen_d08_files.py) on
# throwaway LOCAL databases that look like classi-staging today: every migration up to 20261105010000 applied and recorded,
# and the staging marker. Never touches a hosted database. The files only run on the classi-staging cluster id: the test runs
# copies in which that one constant is replaced by this server's cluster id, and checks that nothing else differs.
# Every check prints PASS: or FAIL:. Usage: sh supabase/tests/staging_d08_test.sh
set -u
T="$(cd "$(dirname "$0")" && pwd)"; REPO="$(cd "$T/../.." && pwd)"
ST="$REPO/supabase/staging"; A=20261114000000_d08_workers; B=20261114010000_d08_enforce
STAGING_ID=7702070854497379551
P="psql -h ${PGSOCK:-/var/tmp/pgc} -p ${PGPORT:-54329} -U postgres -q"
W=$(mktemp -d); BASE=ct_d08_base; DB=ct_d08
pass=0; fail=0
ok() { echo "PASS: $1"; pass=$((pass + 1)); }
ko() { echo "FAIL: $1"; fail=$((fail + 1)); }
q() { $P -d "$DB" -Atc "$1"; }
fresh() { $P -c "drop database if exists $DB" -c "create database $DB template $BASE" >/dev/null; }
run() { $P -d "$DB" -v ON_ERROR_STOP=1 -f "$1" > "$W/out" 2>&1; }
# everything the files could change, as one fingerprint (functions with grants, otp_outbox columns, records, markers)
state() { q "select md5(concat_ws('#',
  (select string_agg(format('%s(%s)|%s|%s|%s|%s|%s|%s', p.proname, pg_get_function_identity_arguments(p.oid), md5(p.prosrc), coalesce(array_to_string(p.proconfig, ','), '-'), p.prosecdef,
     has_function_privilege('anon', p.oid, 'execute'), has_function_privilege('authenticated', p.oid, 'execute'), has_function_privilege('service_role', p.oid, 'execute')), E'\n' order by p.proname, p.oid) from pg_proc p where p.pronamespace='public'::regnamespace),
  (select string_agg(column_name::text, ',' order by column_name) from information_schema.columns where table_schema='public' and table_name='otp_outbox'),
  (select string_agg(version, ',' order by version) from supabase_migrations.schema_migrations),
  (select string_agg(key, ',' order by key) from public.app_secrets)))"; }
expect_refusal() { # <label> <file> <text>: refused, and nothing at all changed
  before=$(state)
  if run "$2"; then ko "$1: it ran"; return; fi
  grep -q "$3" "$W/out" || { ko "$1: not the expected refusal ($(grep -m1 ERROR "$W/out"))"; return; }
  [ "$(state)" = "$before" ] && ok "$1 (refused, nothing changed)" || ko "$1: refused but the state changed"
}
expect_ok() { if run "$2"; then ok "$1"; else ko "$1: $(grep -m1 ERROR "$W/out")"; fi; }

# ---------- a database like classi-staging today (after private photos B) ----------
$P -c "drop database if exists $BASE" -c "create database $BASE" >/dev/null 2>&1
D="env PGOPTIONS=-cclient_min_messages=warning $P -d $BASE -v ON_ERROR_STOP=1"
$D -f "$T/supabase_stub.sql" >/dev/null
$D -c "create schema if not exists supabase_migrations; create table if not exists supabase_migrations.schema_migrations (version text primary key, name text, statements text[])" >/dev/null
for f in "$REPO"/supabase/migrations/*.sql; do
  v=$(basename "$f" | cut -d_ -f1); [ "$v" \> 20261105010000 ] && break
  $D -f "$f" >/dev/null || { echo "FAIL: base: $f did not apply"; exit 1; }
  $D -c "insert into supabase_migrations.schema_migrations (version, name) values ('$v', '$(basename "$f" .sql | cut -d_ -f2-)')" >/dev/null
done
$D -c "insert into public.app_secrets (key, value) values ('deploy_env', 'staging'), ('dispatch_secret', 'stg-secret'), ('private_photos_app', 'deployed') on conflict (key) do update set value = excluded.value" >/dev/null
DB=$BASE; BASE_STATE=$(state); DB=ct_d08
LOCAL_ID=$($P -d $BASE -Atc "select system_identifier from pg_control_system()")

# ---------- the files ----------
(cd "$REPO" && PGSOCK=${PGSOCK:-/var/tmp/pgc} PGPORT=${PGPORT:-54329} python3 scripts/staging/gen_d08_files.py --check > "$W/gen" 2>&1) \
  && ok "the staging files are exactly what the generator makes from the committed migrations" || ko "staging files are stale: $(cat "$W/gen")"
for f in apply_$A rollback_$A apply_$B rollback_$B; do
  [ "$(grep -c "$STAGING_ID" "$ST/$f.sql")" = 1 ] || ko "$f: cluster id count"
  sed "s/$STAGING_ID/$LOCAL_ID/" "$ST/$f.sql" > "$W/$f.sql"
  [ "$(diff "$ST/$f.sql" "$W/$f.sql" | grep -c '^[<>]')" = 2 ] && ok "$f: the test copy differs only in the cluster id line" || ko "$f: test copy differs in more"
done
for m in $A $B; do
  awk '/^-- ===== BEGIN MIGRATION/{f=1;next}/^-- ===== END MIGRATION/{f=0}f' "$ST/apply_$m.sql" | cmp -s - "$REPO/supabase/migrations/$m.sql" \
    && ok "apply_$m: the embedded migration is the committed file, byte for byte" || ko "apply_$m: embedded migration differs"
  awk '/^-- ===== BEGIN ROLLBACK/{f=1;next}/^-- ===== END ROLLBACK/{f=0}f' "$ST/rollback_$m.sql" > "$W/body"
  grep -v '^--' "$REPO/supabase/rollback/$m.down.sql" | grep -v '^begin;$' | grep -v '^commit;$' | cmp -s - "$W/body" \
    && ok "rollback_$m: the embedded rollback is the committed down file" || ko "rollback_$m: embedded rollback differs"
done

# ---------- apply A: refusals ----------
fresh; expect_refusal "A outside classi-staging (the committed file)" "$ST/apply_$A.sql" "refusing: not the classi-staging database"
fresh; q "delete from public.app_secrets where key='deploy_env'" >/dev/null; expect_refusal "A without the staging marker" "$W/apply_$A.sql" "not marked staging"
fresh; q "insert into supabase_migrations.schema_migrations (version) values ('20261114000000')" >/dev/null; expect_refusal "A already recorded" "$W/apply_$A.sql" "already recorded"
fresh; q "insert into supabase_migrations.schema_migrations (version) values ('20261106000000')" >/dev/null; expect_refusal "A with a newer migration recorded" "$W/apply_$A.sql" "newest recorded migration is not 20261105010000"
fresh; q "delete from supabase_migrations.schema_migrations where version='20261105010000'" >/dev/null; expect_refusal "A before private photos B" "$W/apply_$A.sql" "newest recorded migration is not 20261105010000"
fresh; q "alter table public.sms_log disable row level security" >/dev/null; expect_refusal "A with RLS off on a public table" "$W/apply_$A.sql" "row level security off"
fresh; q "grant execute on function public.send_reminders() to anon" >/dev/null; q "grant execute on function public.claim_otp(text) to service_role" >/dev/null
q "revoke execute on function public.claim_otp(text) from authenticated" >/dev/null; expect_refusal "A with different execute rights on a dispatch function" "$W/apply_$A.sql" "dispatch functions"
fresh; q "create or replace function public.claim_push(p_secret text, p_limit int default 200) returns jsonb language sql security definer set search_path = public as \$\$ select '{}'::jsonb \$\$" >/dev/null
expect_refusal "A with a changed claim_push body" "$W/apply_$A.sql" "dispatch functions"
fresh; q "alter table public.otp_outbox add column extra text" >/dev/null; expect_refusal "A with an extra otp_outbox column" "$W/apply_$A.sql" "otp_outbox columns"

# ---------- apply A ----------
fresh; expect_ok "A applies on a staging-like database" "$W/apply_$A.sql"
[ "$(q "select count(*) from supabase_migrations.schema_migrations where version = '20261114000000'")" = 1 ] && ok "A recorded once" || ko "A record"
[ "$(q "select count(*) from pg_proc where proname like 'worker\_%' and has_function_privilege('anon', oid, 'execute')")" = 0 ] && ok "after A: anon executes no worker function" || ko "after A: anon worker"
[ "$(q "select count(*) from pg_proc where proname in ('claim_push','claim_otp') and has_function_privilege('anon', oid, 'execute')")" = 2 ] && ok "after A: the old app's path still works (claim_* for anon)" || ko "after A: old path"
AFTER_A=$(state)
expect_refusal "A twice" "$W/apply_$A.sql" "already recorded"
expect_refusal "rollback B before B" "$W/rollback_$B.sql" "newest recorded migration is not 20261114010000"

# ---------- apply B: refusals ----------
expect_refusal "B before the new code handled a wake-up" "$W/apply_$B.sql" "has not handled a wake-up"
q "insert into public.app_secrets (key, value) values ('d08_worker_seen_at', (now() - interval '25 hours')::text) on conflict (key) do update set value = excluded.value" >/dev/null
expect_refusal "B with a wake-up older than 24 hours" "$W/apply_$B.sql" "has not handled a wake-up"
q "set role service_role; select public.worker_wake_ok('stg-secret')" >/dev/null
[ "$(q "select count(*) from public.app_secrets where key = 'd08_worker_seen_at' and value::timestamptz > now() - interval '1 minute'")" = 1 ] && ok "a wake-up with the server key records the marker" || ko "marker not recorded"
AFTER_A_SEEN=$(state)

# ---------- apply B ----------
expect_ok "B applies after a recent wake-up" "$W/apply_$B.sql"
[ "$(q "select count(*) from pg_proc where proname in ('claim_push','claim_otp','log_sms','drop_push_subscriptions')")" = 0 ] && ok "after B: the old anon functions are gone" || ko "after B: old functions"
[ "$(q "select count(*) from information_schema.columns where table_name='otp_outbox' and column_name='otp'")" = 0 ] && ok "after B: no otp column" || ko "after B: otp column"
expect_refusal "B twice" "$W/apply_$B.sql" "already recorded"
expect_refusal "rollback A while B is recorded" "$W/rollback_$A.sql" "newest recorded migration is not 20261114000000"

# ---------- rollbacks restore the exact earlier states ----------
expect_ok "rollback B" "$W/rollback_$B.sql"
[ "$(state)" = "$AFTER_A_SEEN" ] && ok "rollback B gives back exactly the state after A" || ko "rollback B: state differs from after A"
expect_ok "rollback A" "$W/rollback_$A.sql"
[ "$(state)" = "$BASE_STATE" ] && ok "rollback A gives back exactly the state before D-08" || ko "rollback A: state differs from before D-08"
expect_ok "A again after a full rollback" "$W/apply_$A.sql"
[ "$(state)" = "$AFTER_A" ] && ok "…and the same state as the first time" || ko "A again: state differs"

$P -c "drop database if exists $DB" -c "drop database if exists $BASE" >/dev/null 2>&1
rm -rf "$W"
echo "staging D-08 files: $pass passed, $fail failed"
[ "$fail" = 0 ]
